import React from 'react';
import './DashboardPage.css'; // We'll create this next

const DashboardPage = () => {
  // In the future, these numbers will be calculated from real data
  const totalEmployees = 152;
  const facultyCount = 85;
  const staffCount = 67;
  const departments = ['Computer Science', 'Physics', 'Admissions', 'Mathematics', 'Administration'];

  return (
    <div className="dashboard-container">
      <h1 className="dashboard-title">Administrator's Dashboard</h1>
      <div className="dashboard-widgets">

        {/* Widget 1: Total Employees */}
        <div className="widget">
          <h2>Total Staff & Faculty</h2>
          <p className="widget-value">{totalEmployees}</p>
        </div>

        {/* Widget 2: Faculty Count */}
        <div className="widget">
          <h2>Total Faculty</h2>
          <p className="widget-value">{facultyCount}</p>
        </div>

        {/* Widget 3: Staff Count */}
        <div className="widget">
          <h2>Total Staff</h2>
          <p className="widget-value">{staffCount}</p>
        </div>

        {/* Widget 4: Departments List */}
        <div className="widget full-width">
          <h2>Departments & Faculties</h2>
          <ul className="department-list">
            {departments.map(dept => <li key={dept}>{dept}</li>)}
          </ul>
        </div>

      </div>
    </div>
  );
};

export default DashboardPage;
